// doc-sach — Cloudflare Worker cho web "Đọc Sách Bằng Giọng Nói" (bản động)
// - Phục vụ trang đọc sách tại / (trang được nhúng sẵn trong file này).
// - Đăng nhập Google phía máy chủ (OAuth) để đồng bộ Google Drive mà người
//   dùng KHÔNG phải dán Client ID: mã ứng dụng + mã bí mật nằm ở Worker
//   secrets (GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET), refresh token lưu ở
//   KV binding AUTH, khóa "drive:main".
// - Cron mỗi 5 phút làm mới token + ghi mốc quét cuối (móc đồng bộ nền).
// Xem DEPLOY.md để biết các bước triển khai trên Cloudflare dashboard.
// ============================================================================

const REDIRECT_URI = "https://doc-sach.nguyenhailinh140101.workers.dev/auth/callback";
const OAUTH_SCOPE = "https://www.googleapis.com/auth/drive https://www.googleapis.com/auth/userinfo.email";
const AUTH_KEY = "drive:main";
const LAST_SWEEP_KEY = "drive:lastSweep";
const TOKEN_URL = "https://oauth2.googleapis.com/token";
const DRIVE_API = "https://www.googleapis.com/drive/v3";
const DRIVE_UPLOAD_API = "https://www.googleapis.com/upload/drive/v3";

