let _pageHtml = null;
function pageHtml() {
  if (_pageHtml === null) {
    const bin = atob(PAGE_B64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    _pageHtml = new TextDecoder().decode(bytes);
  }
  return _pageHtml;
}

function servePage() {
  return new Response(pageHtml(), {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-cache",
    },
  });
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}

function configProblem(env) {
  if (!env.GOOGLE_CLIENT_ID || !env.GOOGLE_CLIENT_SECRET) {
    return "Máy chủ chưa đặt secret GOOGLE_CLIENT_ID / GOOGLE_CLIENT_SECRET (xem DEPLOY.md).";
  }
  if (!env.AUTH) {
    return "Máy chủ chưa gắn KV binding AUTH (xem DEPLOY.md).";
  }
  return null;
}

async function getRecord(env) {
  if (!env.AUTH) return null;
  try {
    return await env.AUTH.get(AUTH_KEY, "json");
  } catch {
    return null;
  }
}

async function saveRecord(env, record) {
  await env.AUTH.put(AUTH_KEY, JSON.stringify(record));
}

async function refreshAccessToken(env, record) {
  const body = new URLSearchParams({
    client_id: env.GOOGLE_CLIENT_ID,
    client_secret: env.GOOGLE_CLIENT_SECRET,
    refresh_token: record.refresh_token,
    grant_type: "refresh_token",
  });
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.access_token) {
    throw new Error("refresh_failed: " + (data.error_description || data.error || res.status));
  }
  record.accessToken = data.access_token;
  record.accessExp = Date.now() + (Number(data.expires_in) || 3600) * 1000;
  record.updatedAt = new Date().toISOString();
  await saveRecord(env, record);
  return record.accessToken;
}

async function getAccessToken(env, record, forceRefresh = false) {
  if (!forceRefresh && record.accessToken && record.accessExp && record.accessExp > Date.now() + 60_000) {
    return record.accessToken;
  }
  return refreshAccessToken(env, record);
}

// Gọi Drive API bằng token đã lưu; gặp 401 thì làm mới token rồi thử lại 1 lần.
async function driveFetch(env, record, url, init = {}) {
  const call = async (token) => {
    const headers = new Headers(init.headers || {});
    headers.set("authorization", "Bearer " + token);
    return fetch(url, { ...init, headers });
  };
  let res = await call(await getAccessToken(env, record));
  if (res.status === 401) {
    res = await call(await getAccessToken(env, record, true));
  }
  return res;
}

async function getSessionRecord(env, request) {
  if (!env.AUTH) return null;
  const cookie = request.headers.get("cookie") || "";
  const m = cookie.match(/(?:^|;\s*)ds_session=([A-Za-z0-9-]+)/);
  if (!m) return null;
  try {
    return await env.AUTH.get("session:" + m[1], "json");
  } catch {
    return null;
  }
}

function escapeQ(s) {
  return String(s).replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

// ---------------------------------------------------------------------------

async function handleLogin(env) {
  const problem = configProblem(env);
  if (problem) return json({ error: "not_configured", message: problem }, 503);
  const params = new URLSearchParams({
    client_id: env.GOOGLE_CLIENT_ID,
    redirect_uri: REDIRECT_URI,
    response_type: "code",
    scope: OAUTH_SCOPE,
    access_type: "offline",
    prompt: "consent",
  });
  return Response.redirect("https://accounts.google.com/o/oauth2/v2/auth?" + params.toString(), 302);
}

async function handleCallback(env, url) {
  const problem = configProblem(env);
  if (problem) return json({ error: "not_configured", message: problem }, 503);
  const oauthError = url.searchParams.get("error");
  if (oauthError) {
    return json({ error: "oauth_denied", message: "Google trả lỗi: " + oauthError }, 400);
  }
  const code = url.searchParams.get("code");
  if (!code) return json({ error: "missing_code", message: "Thiếu mã đăng nhập từ Google." }, 400);

  const tokenRes = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      code,
      client_id: env.GOOGLE_CLIENT_ID,
      client_secret: env.GOOGLE_CLIENT_SECRET,
      redirect_uri: REDIRECT_URI,
      grant_type: "authorization_code",
    }),
  });
  const tokens = await tokenRes.json().catch(() => ({}));
  if (!tokenRes.ok || !tokens.access_token) {
    return json(
      { error: "token_exchange_failed", message: "Đổi mã lấy token thất bại: " + (tokens.error_description || tokens.error || tokenRes.status) },
      502,
    );
  }

  let email = "";
  try {
    const infoRes = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
      headers: { authorization: "Bearer " + tokens.access_token },
    });
    const info = await infoRes.json().catch(() => ({}));
    email = info.email || "";
  } catch { /* email để trống nếu userinfo lỗi */ }

  const previous = await getRecord(env);
  const record = {
    refresh_token: tokens.refresh_token || (previous && previous.refresh_token) || "",
    email: email || (previous && previous.email) || "",
    accessToken: tokens.access_token,
    accessExp: Date.now() + (Number(tokens.expires_in) || 3600) * 1000,
    updatedAt: new Date().toISOString(),
  };
  if (!record.refresh_token) {
    return json(
      { error: "no_refresh_token", message: "Google không cấp refresh token. Hãy thu hồi quyền cũ của ứng dụng trong tài khoản Google rồi đăng nhập lại." },
      502,
    );
  }
  await saveRecord(env, record);

  // Cookie phiên: id ngẫu nhiên -> cùng bản ghi, để trình duyệt "đã đăng nhập".
  const sessionId = crypto.randomUUID();
  await env.AUTH.put("session:" + sessionId, JSON.stringify(record), { expirationTtl: 60 * 60 * 24 * 30 });
  return new Response(null, {
    status: 302,
    headers: {
      location: "/",
      "set-cookie": "ds_session=" + sessionId + "; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000",
    },
  });
}

async function handleStatus(env, request) {
  const problem = configProblem(env);
  if (problem) return json({ connected: false, error: "not_configured", message: problem });
  const record = (await getRecord(env)) || (await getSessionRecord(env, request));
  if (!record || !record.refresh_token) return json({ connected: false });
  try {
    await getAccessToken(env, record); // làm mới token nếu sắp hết hạn
    return json({ connected: true, email: record.email || "" });
  } catch {
    return json({ connected: false, email: record.email || "", error: "token_invalid" });
  }
}

// Mọi endpoint /api/drive/* đều cần bản ghi đăng nhập còn hiệu lực.
async function requireDrive(env) {
  const problem = configProblem(env);
  if (problem) return { errorResponse: json({ error: "not_configured", message: problem }, 503) };
  const record = await getRecord(env);
  if (!record || !record.refresh_token) {
    return { errorResponse: json({ error: "not_connected", message: "Chưa kết nối Google Drive — hãy bấm “Kết nối Google Drive”." }, 401) };
  }
  return { record };
}

async function handleDriveFiles(env, url) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  const q = (url.searchParams.get("q") || "").trim();
  const folder = (url.searchParams.get("folder") || "").trim();
  const clauses = ["trashed = false"];
  if (q) clauses.push("name contains '" + escapeQ(q) + "'");
  else if (folder) clauses.push("'" + escapeQ(folder) + "' in parents");
  else clauses.push("'root' in parents");
  const params = new URLSearchParams({
    q: clauses.join(" and "),
    fields: "files(id,name,mimeType,modifiedTime,size,parents),nextPageToken",
    orderBy: "folder,name",
    pageSize: "100",
  });
  const res = await driveFetch(env, record, DRIVE_API + "/files?" + params.toString());
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  return json(data);
}

async function findFileByName(env, record, name, parentId) {
  const clauses = ["name = '" + escapeQ(name) + "'", "trashed = false"];
  if (parentId) clauses.push("'" + escapeQ(parentId) + "' in parents");
  const params = new URLSearchParams({
    q: clauses.join(" and "),
    fields: "files(id,name,mimeType,modifiedTime)",
    pageSize: "1",
  });
  const res = await driveFetch(env, record, DRIVE_API + "/files?" + params.toString());
  if (!res.ok) return null;
  const data = await res.json().catch(() => ({}));
  return data.files && data.files.length ? data.files[0] : null;
}

async function handleDriveUpload(env, request) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_json", message: "Thân yêu cầu phải là JSON." }, 400);
  }
  const name = (body.name || "").trim();
  const mimeType = (body.mimeType || "text/plain; charset=utf-8").trim();
  const parentId = (body.parentId || "").trim();
  const contentText = typeof body.contentText === "string" ? body.contentText : "";
  if (!name) return json({ error: "missing_name", message: "Thiếu tên file." }, 400);

  const existing = await findFileByName(env, record, name, parentId);
  if (existing) {
    // Cập nhật đúng file cũ (chỉ thay nội dung) — không tạo bản trùng.
    const res = await driveFetch(env, record, DRIVE_UPLOAD_API + "/files/" + existing.id + "?uploadType=media", {
      method: "PATCH",
      headers: { "content-type": mimeType },
      body: contentText,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
    }
    return json({ ...data, updated: true });
  }

  const metadata = { name };
  if (parentId) metadata.parents = [parentId];
  const boundary = "doc-sach-" + crypto.randomUUID();
  const multipart =
    "--" + boundary + "\r\n" +
    "content-type: application/json; charset=utf-8\r\n\r\n" +
    JSON.stringify(metadata) + "\r\n" +
    "--" + boundary + "\r\n" +
    "content-type: " + mimeType + "\r\n\r\n" +
    contentText + "\r\n" +
    "--" + boundary + "--";
  const res = await driveFetch(env, record, DRIVE_UPLOAD_API + "/files?uploadType=multipart", {
    method: "POST",
    headers: { "content-type": "multipart/related; boundary=" + boundary },
    body: multipart,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  return json({ ...data, created: true });
}

async function handleDriveDownload(env, url) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  const id = (url.searchParams.get("id") || "").trim();
  if (!id) return json({ error: "missing_id", message: "Thiếu id file." }, 400);
  const res = await driveFetch(env, record, DRIVE_API + "/files/" + encodeURIComponent(id) + "?alt=media");
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  const headers = new Headers();
  headers.set("content-type", res.headers.get("content-type") || "application/octet-stream");
  const len = res.headers.get("content-length");
  if (len) headers.set("content-length", len);
  return new Response(res.body, { status: 200, headers });
}

// ---------------------------------------------------------------------------

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    try {
      if (path === "/auth/login") return await handleLogin(env);
      if (path === "/auth/callback") return await handleCallback(env, url);
      if (path === "/api/status") return await handleStatus(env, request);
      if (path === "/api/drive/files" && request.method === "GET") return await handleDriveFiles(env, url);
      if (path === "/api/drive/upload" && request.method === "POST") return await handleDriveUpload(env, request);
      if (path === "/api/drive/download" && request.method === "GET") return await handleDriveDownload(env, url);
      if (path.startsWith("/api/") || path.startsWith("/auth/")) {
        return json({ error: "not_found", message: "Không có endpoint này." }, 404);
      }
      return servePage(); // mọi đường còn lại -> trang đọc sách (SPA fallback)
    } catch (err) {
      return json({ error: "server_error", message: String((err && err.message) || err) }, 500);
    }
  },

  // Quét nền mỗi 5 phút: làm mới token để phiên Drive không chết, ghi mốc
  // quét cuối. Đây là móc để chạy hàng đợi đồng bộ Drive ở các bước sau.
  async scheduled(event, env, ctx) {
    const sweep = async () => {
      if (!env.AUTH) return;
      const record = await getRecord(env);
      if (record && record.refresh_token && env.GOOGLE_CLIENT_ID && env.GOOGLE_CLIENT_SECRET) {
        try { await refreshAccessToken(env, record); } catch { /* token lỗi sẽ báo ở /api/status */ }
      }
      await env.AUTH.put(LAST_SWEEP_KEY, new Date().toISOString());
    };
    if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(sweep());
    else await sweep();
  },
};
